import axios from 'axios';
import { API_CONFIG } from '@/config/config';
import { ElMessage } from 'element-plus';

export const chatModule = {
  namespaced: true,
  state: {
    recentChats: [],    // 所有最近聊天（按时间排序）
    recentGroups: [],   // 最近群聊
    recentUsers: [],    // 最近单聊
    joinedGroups: []    // 已加入的群聊列表
  },
  mutations: {
    // 添加或更新最近聊天（自动区分群聊和单聊）
ADD_RECENT_CHAT(state, chat) {
  const chatId = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
  const isGroup = chat.isGroup === true;
  
  // 确保不会将私聊添加到群聊列表
  const targetList = isGroup ? state.recentGroups : state.recentUsers;
  const existingIndex = targetList.findIndex(item => 
    typeof item.id === 'string' ? parseInt(item.id, 10) === chatId : item.id === chatId
  );
  
  if (existingIndex !== -1) {
    targetList.splice(existingIndex, 1);
  }
  
  // 确保不会将私聊用户添加到joinedGroups
  if (isGroup) {
    targetList.unshift({ 
      ...chat, 
      id: chatId,
      // 确保不覆盖已存在的群组成员信息
      members: chat.members || (state.joinedGroups.find(g => g.id === chatId)?.members || []
    )});
  } else {
    targetList.unshift({ ...chat, id: chatId });
  }
  
  if (targetList.length > 50) {
    targetList.pop();
  }
  
  // 更新统一列表
  const allChats = [...state.recentGroups, ...state.recentUsers];
  allChats.sort((a, b) => {
    const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
    const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
    return timeB - timeA;
  });
  
  state.recentChats = allChats.slice(0, 50);
},
    
    // 初始化最近聊天
    INIT_RECENT_CHATS(state, chats) {
      const normalizedChats = chats.map(chat => {
        const id = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
        return { ...chat, id };
      });
      
      const groups = normalizedChats.filter(chat => chat.isGroup === true);
      const users = normalizedChats.filter(chat => chat.isGroup !== true);
      
      state.recentGroups = groups;
      state.recentUsers = users;
      
      const allChats = [...groups, ...users];
      allChats.sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
      
      state.recentChats = allChats;
    },
    
    // 初始化已加入的群聊
    INIT_JOINED_GROUPS(state, groups) {
      state.joinedGroups = groups.map(group => ({
        ...group,
        id: typeof group.id === 'string' ? parseInt(group.id, 10) : group.id,
        target_id: typeof group.target_id === 'string' ? parseInt(group.target_id, 10) : group.target_id,
        isGroup: true
      }));
    },
    
    // 更新单个群聊信息（不自动添加到最近聊天）
    UPDATE_JOINED_GROUP(state, updatedGroup) {
      const groupId = typeof updatedGroup.id === 'string' ? parseInt(updatedGroup.id, 10) : updatedGroup.id;
      const index = state.joinedGroups.findIndex(g => g.id === groupId);
      
      if (index !== -1) {
        state.joinedGroups.splice(index, 1, { ...state.joinedGroups[index], ...updatedGroup });
      } else {
        state.joinedGroups.push({ ...updatedGroup, id: groupId, isGroup: true });
      }
      
      // 特别注意：这里不调用 ADD_RECENT_CHAT，确保不会自动添加到最近聊天
    },
    
    // 更新未读计数
    UPDATE_UNREAD_COUNT(state, { targetId, count }) {
      const targetIdNum = typeof targetId === 'string' ? parseInt(targetId, 10) : targetId;
      
      // 更新最近聊天列表
      const updateChatList = (list) => {
        const index = list.findIndex(item => item.id === targetIdNum);
        if (index !== -1) {
          list[index].unreadCount = count;
        }
      };
      
      updateChatList(state.recentGroups);
      updateChatList(state.recentUsers);
      
      // 更新已加入的群聊列表
      const groupIndex = state.joinedGroups.findIndex(g => g.id === targetIdNum);
      if (groupIndex !== -1) {
        state.joinedGroups[groupIndex].unreadCount = count;
      }
    },
    
    // 清除所有聊天记录
    CLEAR_ALL_CHATS(state) {
      state.recentChats = [];
      state.recentGroups = [];
      state.recentUsers = [];
      state.joinedGroups = [];
    }
  },
  actions: {
    // 加载最近聊天列表
    async loadRecentChats({ commit, rootState }) {
      try {
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        const formattedChats = response.data.map(chat => ({
          id: chat.target_id,
          username: chat.target_username,
          photo: chat.target_photo,
          lastMessage: chat.last_message,
          lastMessageTime: chat.last_message_time,
          unreadCount: chat.unread_count || 0,
          isGroup: chat.is_group || false,
          members_count: chat?.members_count || 0,
          group_members: chat?.group_members || [],
          group_owner_id: chat?.group_owner_id,
          
        }));
        
        commit('INIT_RECENT_CHATS', formattedChats);
        return formattedChats;
      } catch (error) {
        console.error('加载最近聊天列表失败:', error);
        return [];
      }
    },
    
    // 加载已加入的群聊
    async loadJoinedGroups({ commit, rootState }) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法加载已加入的群聊');
          ElMessage.warning('请先登录');
          return [];
        }
        
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/get-joined-groups/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        const formattedGroups = (response.data || []).map(group => ({
          id: group.target_id || group.group_id || group.id,
          username: group.name || '未命名群聊',
          photo: group.group_photo || null,
          target_id: group.target_id || group.group_id || group.id,
          // isGroup: true,
          // lastMessage: group.last_message || '',
          created_at: group.created_at || new Date().toISOString(),
          unreadCount: group.unread_count || 0,
          members: group.group_members || group.members || [],
          membersCount: group.members_count || (group.group_members ? group.group_members.length : 0) || 0,
          ownerId: group.creator_id || null
        }));
        
        commit('INIT_JOINED_GROUPS', formattedGroups);
        return formattedGroups;
      } catch (error) {
        console.error('加载已加入的群聊失败:', error);
        ElMessage.error('加载已加入的群聊失败，请重试');
        return [];
      }
    },
    
    // 刷新单个群聊信息（不自动添加到最近聊天）
    async refreshJoinedGroup({ commit, rootState }, groupId) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法刷新群聊信息');
          return null;
        }
        
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${groupId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        if (response.data) {
          const updatedGroup = {
            id: groupId,
            ...response.data,
            isGroup: true
          };
          
          // 只更新已加入的群列表，不添加到最近聊天
          commit('UPDATE_JOINED_GROUP', updatedGroup);
          return updatedGroup;
        }
      } catch (error) {
        console.error(`刷新群聊 ${groupId} 信息失败:`, error);
        ElMessage.error('刷新群聊信息失败');
        return null;
      }
    },
    
    // 保存最近聊天
    async saveRecentChat({ rootState }, chatInfo) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法保存最近聊天记录');
          return;
        }
        
        if (!chatInfo) {
          console.error('saveRecentChat 错误：未提供聊天用户信息');
          return;
        }
        
        const userId = rootState.user.id;
        const isGroup = chatInfo.isGroup === true;
        console.log("打印群聊信息: ", chatInfo)
        const recentChatData = {
          user_id: userId,
          target_id: chatInfo.id,
          target_username: chatInfo.username,
          target_photo: chatInfo.photo,
          last_message: chatInfo.lastMessage || '',
          last_message_time: chatInfo.lastMessageTime || new Date().toISOString(),
          unread_count: chatInfo.unreadCount || 0,
          members: chatInfo?.members,
          is_group: isGroup
        };
        
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats`, recentChatData, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
      } catch (error) {
        console.error('保存最近聊天记录失败:', error);
        throw error;
      }
    },
    
    // 清除未读计数
    async clearUnreadCount({ commit, rootState }, targetId) {
      try {
        const userId = rootState.user.id;
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/recent-chats/${userId}/clear-unread/${targetId}`, {}, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        commit('UPDATE_UNREAD_COUNT', { targetId, count: 0 });
      } catch (error) {
        console.error('清除未读计数失败:', error);
        throw error;
      }
    },
    
    // 登出时清除所有聊天记录
    async clearAllChats({ commit }) {
      commit('CLEAR_ALL_CHATS');
    },
    
    // 手动添加群聊到最近聊天（只有用户主动发起聊天时调用）
    async addGroupToRecent({ commit, dispatch }, groupInfo) {
      commit('ADD_RECENT_CHAT', groupInfo);
      await dispatch('saveRecentChat', groupInfo);
    }
  },
  getters: {
    getRecentChats: state => state.recentChats,
    getRecentGroups: state => state.recentGroups,
    getRecentUsers: state => state.recentUsers,
    getJoinedGroups: state => state.joinedGroups,
    
    getChatById: state => (id) => {
      const idNum = typeof id === 'string' ? parseInt(id, 10) : id;
      return state.recentChats.find(chat => chat.id === idNum);
    },
    
    getJoinedGroupById: state => (id) => {
      const idNum = typeof id === 'string' ? parseInt(id, 10) : id;
      return state.joinedGroups.find(group => group.id === idNum);
    },
    
    getTotalUnreadCount: state => {
      return state.recentChats.reduce((total, chat) => total + (chat.unreadCount || 0), 0);
    },
    
    getJoinedGroupsCount: state => state.joinedGroups.length
  }
};

export default chatModule;
